const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lut Desert region (rough bounding box)
  const lutDesert = ee.Geometry.Polygon([
    [56.0, 28.0],
    [60.0, 28.0],
    [60.0, 32.0],
    [56.0, 32.0],
    [56.0, 28.0]
  ]);

  // 2. Date range for 2018
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // Function to process MODIS LST collection
  function getLSTCollection(collectionName) {
    return ee.ImageCollection(collectionName)
      .filterBounds(lutDesert)
      .filterDate(startDate, endDate)
      .map(function(img) {
        // Quality mask: bits 0-1 of QC_Day = 00 (good quality)
        const qa = img.select('QC_Day');
        const qualityMask = qa.bitwiseAnd(3).eq(0); // 00 = good

        // Convert LST from Kelvin to Celsius: scale 0.02, then -273.15
        const lstC = img.select('LST_Day_1km')
          .multiply(0.02)
          .subtract(273.15)
          .updateMask(qualityMask);

        return img.select([]).addBands(lstC.rename('LST_C'));
      });
  }

  // Try Terra MODIS first, fallback to Aqua if empty
  let collection = getLSTCollection('MODIS/061/MOD11A1');
  let collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Terra MODIS empty, trying Aqua...');
    collection = getLSTCollection('MODIS/061/MYD11A1');
    collectionSize = collection.size().getInfo();
  }

  console.log(`2018 LST Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Create maximum temperature composite for 2018
  const maxTempImg = collection.select('LST_C').max();

  // Count valid pixels in region
  const pixelCount = maxTempImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lutDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  console.log(`Valid pixels in max composite: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Get maximum temperature in region
  const maxTemp = maxTempImg.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lutDesert,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  console.log(`Maximum LST in 2018: ${maxTemp ? maxTemp.toFixed(2) : 'null'}°C`);

  // Validate result
  if (maxTemp === null || maxTemp === undefined || isNaN(maxTemp)) {
    console.log('<answer>C3</answer>');
  } else if (maxTemp > 75) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
